using Keynote.Core;
using Keynote.Midi;
using Keynote.Online;
namespace Keynote.Tests;
public class DiscoveryTests {
 sealed class Provider(Func<string,int,CancellationToken,Task<CatalogPage>> run) : IMidiCatalogProvider { public int Calls; public Task<CatalogPage> SearchAsync(string q,int p,CancellationToken t) { Interlocked.Increment(ref Calls); return run(q,p,t); } public Uri DownloadUri(CatalogResult r)=>new("https://midisss.com/"); }
 static CatalogResult Item(string provider,string id,string title="Song",string description="")=>new(provider,id,title,"Artist",description,"Unknown","https://example.test/"+provider+id);
 [Fact] public async Task SearchesProvidersConcurrentlyAndIsolatesFailures() { var both=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); int started=0; var good=new Provider(async(q,p,t)=>{if(Interlocked.Increment(ref started)==2)both.TrySetResult(); await both.Task.WaitAsync(t);return new(new[]{Item("good","1")},false);}); var bad=new Provider(async(q,p,t)=>{if(Interlocked.Increment(ref started)==2)both.TrySetResult(); await both.Task.WaitAsync(t);throw new InvalidOperationException("offline");}); var service=new DiscoverySearchService(new Dictionary<string,IMidiCatalogProvider>{{"good",good},{"bad",bad}}); using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(2)); var batch=await service.SearchAsync("song",0,null,timeout.Token); Assert.Single(batch.Results); Assert.True(batch.Providers.Single(x=>x.Provider=="good").Succeeded); Assert.Contains("offline",batch.Providers.Single(x=>x.Provider=="bad").Error); }
 [Fact] public async Task CacheAndPaginationArePerProviderAndPage() { var provider=new Provider((q,p,t)=>Task.FromResult(new CatalogPage(new[]{Item("a",p.ToString())},p==0))); var service=new DiscoverySearchService(new Dictionary<string,IMidiCatalogProvider>{{"a",provider}}); var first=await service.SearchAsync("song",0,null,CancellationToken.None); Assert.True(first.Providers[0].HasMore); await service.SearchAsync("song",0,null,CancellationToken.None); Assert.Equal(1,provider.Calls); var next=await service.SearchAsync("song",1,new[]{"a"},CancellationToken.None); Assert.False(next.Providers[0].HasMore); Assert.Equal("1",next.Results[0].Id); Assert.Equal(2,provider.Calls); }
 [Fact] public void DeduplicationPreservesDistinctArrangementsAndHashSources() { var a=Item("a","1","Same","piano"); var b=Item("b","2","Same","piano"); Assert.Equal(2,DiscoverySearchService.Merge(new[]{a,b}).Count); var hash=new string('a',64); var merged=Assert.Single(DiscoverySearchService.Merge(new[]{a with {Sha256=hash},b with {Sha256=hash}})); Assert.Equal(2,merged.Sources!.Count); Assert.Equal(2,DiscoverySearchService.Merge(new[]{a with {Id=""},b with {Id=""}}).Count); var direct="https://example.test/same.mid"; Assert.Single(DiscoverySearchService.Merge(new[]{a with {DirectUrl=direct},b with {DirectUrl=direct}})); Assert.Equal(2,DiscoverySearchService.Merge(new[]{a with {DirectUrl=direct},b with {DirectUrl=direct,Description="orchestral"}}).Count); Assert.Equal(2,DiscoverySearchService.Merge(new[]{a with {DirectUrl="https://example.test/A.mid"},b with {DirectUrl="https://example.test/a.mid"}}).Count); }
 [Fact] public async Task FailedProviderReportsItsPreviousSuccess() { bool fail=false; var provider=new Provider((q,p,t)=>fail ? Task.FromException<CatalogPage>(new InvalidOperationException("offline")) : Task.FromResult(new CatalogPage(Array.Empty<CatalogResult>(),false))); var service=new DiscoverySearchService(new Dictionary<string,IMidiCatalogProvider>{{"a",provider}}); var initial=await service.SearchAsync("first",0,null,CancellationToken.None); fail=true; var later=await service.SearchAsync("second",0,null,CancellationToken.None); Assert.False(later.Providers[0].Succeeded); Assert.Equal(initial.Providers[0].LastSuccess,later.Providers[0].LastSuccess); }
 [Fact] public async Task CancellationPropagatesAndDoesNotCachePartialSearch() { var provider=new Provider(async(q,p,t)=>{await Task.Delay(Timeout.Infinite,t);return new(Array.Empty<CatalogResult>(),false);}); var service=new DiscoverySearchService(new Dictionary<string,IMidiCatalogProvider>{{"a",provider}}); using var cts=new CancellationTokenSource(); var task=service.SearchAsync("song",0,null,cts.Token); cts.Cancel(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); Assert.Equal(1,provider.Calls); }
 [Fact] public async Task DebounceCancelsStaleSearch() { using var debounce=new SearchDebouncer(); var observed=new List<string>(); var first=debounce.ScheduleAsync(t=>{observed.Add("old");return Task.CompletedTask;},TimeSpan.FromMilliseconds(100)); var second=debounce.ScheduleAsync(t=>{observed.Add("new");return Task.CompletedTask;},TimeSpan.FromMilliseconds(20)); await Task.WhenAll(first,second); Assert.Equal(new[]{"new"},observed); }
 [Fact] public async Task HistorySuggestionsAreLocallyDerivedAndPersisted() { var dir=Path.Combine(Path.GetTempPath(),"keynote-history-"+Guid.NewGuid().ToString("N")); try { var store=new SearchHistoryStore(Path.Combine(dir,"history.json")); var history=SearchHistoryStore.Add(Array.Empty<string>(),"Moonlight Sonata"); history=SearchHistoryStore.Add(history,"Bach"); await store.SaveAsync(history,CancellationToken.None); var restored=await store.LoadAsync(CancellationToken.None); Assert.Equal(new[]{"Moonlight Sonata"},SearchHistoryStore.Suggest(restored,"moon")); Assert.Empty(SearchHistoryStore.Suggest(restored,"fabricated")); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public void PreflightUsesOnlySelectedTracksAndReportsOverlapsAndMapping() { var song=new MidiSong("s",new[]{new MidiTrack(0,new[]{new MidiNote(60,90,TimeSpan.Zero,TimeSpan.FromSeconds(1),0),new MidiNote(60,90,TimeSpan.FromMilliseconds(500),TimeSpan.FromSeconds(1),0),new MidiNote(64,90,TimeSpan.Zero,TimeSpan.FromSeconds(1),0)}),new MidiTrack(1,new[]{new MidiNote(72,90,TimeSpan.Zero,TimeSpan.FromSeconds(1),1)})}); var mapping=new KeyboardMapping{Keys=new(){{60,"A"}}}; var p=ArrangementAnalyzer.Analyze(song,mapping,0,new[]{0}); Assert.Equal(3,p.TotalNotes); Assert.Equal(2,p.PlayableNotes); Assert.Equal(new[]{64},p.UnmappedPitches); Assert.Equal(3,p.MaxConcurrent); Assert.Equal(1,p.OverlappingNotes); Assert.Equal(1,p.ExcludedNotes); }
 [Fact] public async Task LibraryDuplicatesRetainProviderAttribution() { var dir=Path.Combine(Path.GetTempPath(),"keynote-source-"+Guid.NewGuid().ToString("N")); try { var data=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid")); var lib=new MidiLibraryService(dir,new MidiImporter()); var first=await lib.AddAsync(data,Item("A","1"),CancellationToken.None); var second=await lib.AddAsync(data,Item("B","2"),CancellationToken.None); Assert.True(second.Duplicate); Assert.Equal(2,second.Entry.Sources!.Count); Assert.Equal(2,(await lib.ListAsync(CancellationToken.None)).Single().Sources!.Count); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
}
